const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程' },
      { kind: 'text', payload: '5x + 2 = 2x + 8' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '5x - 2x = 8 - 2' },
      { kind: 'text', payload: '把含 x 的项移到左边，常数项移到右边' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '3x = 6' },
      { kind: 'text', payload: '合并 x 项与常数项' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x = 2' },
      { kind: 'text', payload: '两边同时除以 3' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.max(14, Math.min(w, h) * 0.035);
    var titleY = margin + 2;
    var origY = titleY + Math.max(30, h * 0.075);
    var cardsTop = origY + Math.max(34, h * 0.085);
    var bottom = h - margin;
    var gap = Math.max(10, Math.min(18, h * 0.03));
    var cardH = (bottom - cardsTop - gap * 2) / 3;
    var cardX = margin;
    var cardW = w - margin * 2;
    var badgeR = Math.min(22, Math.max(14, cardH * 0.18));
    var badgeX = cardX + badgeR + 14;
    var textX = cardX + badgeR * 2 + 30;
    var paths = [];
    var children = [];

    function rect(x, y, width, height) {
      return [['M', x, y], ['L', x + width, y], ['L', x + width, y + height], ['L', x, y + height], ['Z']];
    }

    function addPath(id, commands, fill, strokeWidth) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (strokeWidth) {
        node.stroke = { width: strokeWidth };
      }
      children.push(node);
    }

    function addLabel(contentIndex, x, y, hAlign, vAlign, color) {
      children.push({
        type: 'label',
        contentId: metrics[contentIndex].contentId,
        anchor: { x: x, y: y },
        hAlign: hAlign,
        vAlign: vAlign,
        color: color
      });
    }

    addLabel(0, w / 2, titleY, 'center', 'top', '#1F3550');

    var origW = Math.min(cardW * 0.72, 320);
    var origX = (w - origW) / 2;
    var origRectY = origY - 10;
    var origRectH = 36;
    addPath('origBg', rect(origX, origRectY, origW, origRectH), '#E8F0FA', 0);
    addLabel(1, w / 2, origY + 8, 'center', 'middle', '#1F3550');

    var stepTitles = [3, 7, 11];
    var stepEqs = [4, 8, 12];
    var stepNums = [2, 6, 10];
    var stepNotes = [5, 9, 13];

    for (var i = 0; i < 3; i++) {
      var top = cardsTop + i * (cardH + gap);
      addPath('card' + i, rect(cardX, top, cardW, cardH), '#F2F6FC', 0);
      addPath('accent' + i, rect(cardX, top, 6, cardH), '#3B6FB6', 0);
      var cy = top + cardH / 2;
      addPath('badge' + i, visualSdk.circle(badgeX, cy, badgeR), '#3B6FB6', 0);
      addLabel(stepNums[i], badgeX, cy, 'center', 'middle', '#FFFFFF');

      var titleY2 = top + cardH * (cardH >= 96 ? 0.30 : 0.34);
      var eqY2 = top + cardH * (cardH >= 96 ? 0.60 : 0.68);
      addLabel(stepTitles[i], textX, titleY2, 'left', 'middle', '#1F3550');
      addLabel(stepEqs[i], textX, eqY2, 'left', 'middle', '#0F2A44');

      if (cardH >= 96) {
        addLabel(stepNotes[i], textX, top + cardH * 0.84, 'left', 'middle', '#5B6B7F');
      }

      if (i < 2) {
        var y1 = top + cardH + 1;
        var y2 = top + cardH + gap - 1;
        var ax = badgeX;
        addPath('arrowLine' + i, [['M', ax, y1], ['L', ax, y2 - 4]], '#3B6FB6', 2);
        addPath('arrowHead' + i, [['M', ax - 4, y2 - 4], ['L', ax + 4, y2 - 4], ['L', ax, y2], ['Z']], '#3B6FB6', 0);
      }
    }

    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
